"SELECT DISTINCT\r\nRCT.[CLAIM_ID],\r\nCASE\r\n\tWHEN STS.[Current Status] IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date])) BETWEEN 0 AND 7 THEN '     0-7 Days'\r\n\tWHEN STS.[Current Status] IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date])) BETWEEN 8 AND 14 THEN '    8-14 Days'\r\n\tWHEN STS.[Current Status] IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date])) BETWEEN 15 AND 29 THEN '   15-29 Days'\r\n\tWHEN STS.[Current Status] IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date])) BETWEEN 30 AND 59 THEN '  30-59 Days'\r\n\tWHEN STS.[Current Status] IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date])) BETWEEN 60 AND 89 THEN ' 60-89 Days'\r\n\tWHEN STS.[Current Status] IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date])) >= 90 THEN '90+ Days'\r\n\tWHEN STS.[Current Status] NOT IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date])) BETWEEN 0 AND 7 THEN '     0-7 Days'\r\n\tWHEN STS.[Current Status] NOT IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date])) BETWEEN 8 AND 14 THEN '    8-14 Days'\r\n\tWHEN STS.[Current Status] NOT IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date])) BETWEEN 15 AND 29 THEN '   15-29 Days'\r\n\tWHEN STS.[Current Status] NOT IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date])) BETWEEN 30 AND 59 THEN '  30-59 Days'\r\n\tWHEN STS.[Current Status] NOT IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date])) BETWEEN 60 AND 89 THEN ' 60-89 Days'\r\n\tWHEN STS.[Current Status] NOT IN ('Full Denial', 'Paid In Full', 'Partial Denial', 'Void') AND (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date])) >= 90 THEN '90+ Days'\r\n\tELSE NULL\r\nEND \t\t\t\tAS [Suspended Age Group],\r\nCASE\r\n\tWHEN STS.[Current Status] IN ('Suspended', 'Allowed', 'Full Denial-INV', 'Payment Pending', 'Open') THEN (DAYDIFF(CURRENTDATE(),RCT.[Receipt Date]))\r\n    ELSE (DAYDIFF(STS.[Current Status Date],RCT.[Receipt Date]))\r\nEND AS Age\r\n\r\nFROM [Receipt Date] AS RCT \r\nJOIN [Claim Status] AS STS ON RCT.[CLAIM_ID] = STS.[CLAIM_ID]"
